import subprocess

def get_ls_result_snippet(dir_path: str) -> str:
    try:
        process = subprocess.Popen(['ls', '-l', dir_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            return ""
        return stdout.decode('utf-8').strip()
    except Exception:
        return ""

